function knnDist(a,b){ var s=0; for(var i=0;i<a.length;i++){ var d=a[i]-b[i]; s+=d*d; } return Math.sqrt(s); }
function knnPredict(train,x,k){ var arr=train.map(function(t){return {d:knnDist(t.x,x),y:t.y};}); arr.sort(function(p,q){return p.d-q.d;});
  var cnt={}; for(var i=0;i<k;i++){ var c=arr[i].y; cnt[c]=(cnt[c]||0)+1; }
  var best=null,bv=-1; for(var c in cnt) if(cnt[c]>bv){bv=cnt[c];best=+c;} return best; }
var EXPORTS={knnDist:knnDist, knnPredict:knnPredict};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KnnForgePure = EXPORTS; }
